irm_msg_on_default_value":{"msg":"","val_for_confirm":true},"nlu_text_input":false,"nlu_confirmation_prompt":false,"cardFields":[],"expert_mode":false,"acknowledge_msg":"vaVars.previous_graph_node="Start___873db8fa26ad4d9a8ecc32d3c3e226f6";var ackMsg=null;ackMsg=gs.getMessageLang("va:topic:2900e4a72b3fee10d4dffd74ce91bfe8:node:873db8fa26ad4d9a8ecc32d3c3e226f6:field:GreetingMsg", vaContext.getRequesterLang());ackMsg;"},{"name":"__silent_ScriptedAction_f82185e9de674056baf341ae59029d45","applicable":"(vaVars.previous_graph_node=="Start___873db8fa26ad4d9a8ecc32d3c3e226f6")","direction":"Input","required":true,"prompt_msg":"vaVars.previous_graph_node="User Lookup___f82185e9de674056baf341ae59029d45";(function execute() {(function execute() {

 var identityGr = new GlideRecordSecure("x_aleen_snguardian_identity");
 identityGr.addQuery('email', vaInputs.user_email);
 identityGr.addQuery('is_deleted', false);
 identityGr.query();
 if (identityGr.next()) {
 var user_type = identityGr.type.code;
 vaVars.guardian_user_sys_id = identityGr.sys_id.toString();
 vaVars.user_name = identityGr.full_name.toString();
 vaVars.user_photo = identityGr.photo.toString();
 vaVars.user_type = identityGr.type.name.toString();
 vaVars.user_type_sys_id = identityGr.type.toString();
 if (user_type == 'VISITOR') {
 var visitorGr = new GlideRecordSecure("x_aleen_snguardian_visitor");
 if (visitorGr.get(identityGr.sys_id)) {
 vaVars.user_status = visitorGr.visitor_status.name.toString();
 vaVars.user_number = visitorGr.number.toString();
 }
 } else {
 vaVars.user_status = identityGr.status.name.toString();
 vaVars.user_number = identityGr.number.toString();
 }
 } else {
 vaVars.guardian_user_sys_id = '';
 vaVars.user_name = '';
 vaVars.user_photo = '';
 vaVars.user_type = '';
 vaVars.user_status = '';
 vaVars.user_number = '';
 vaVars.user_type_sys_id ='';
 }

})()
